changeSet.sql:
INSERT INTO krrg_roles (id, title)
SELECT 1, 'admin'
    WHERE NOT EXISTS (SELECT 1 FROM krrg_roles WHERE title = 'admin');

INSERT INTO krrg_roles (id, title)
SELECT 2, 'user'
    WHERE NOT EXISTS (SELECT 1 FROM krrg_roles WHERE title = 'user');

ALTER TABLE krrg_settings ALTER COLUMN is_admin SET DEFAULT FALSE;
ALTER TABLE krrg_setting_groups ALTER COLUMN is_admin SET DEFAULT FALSE;

UPDATE krrg_setting_groups
SET is_admin = FALSE
WHERE is_admin IS NULL OR code <> 'admin';

UPDATE krrg_setting_groups
SET is_admin = TRUE
WHERE code = 'admin';

UPDATE krrg_settings s
SET is_admin = FALSE
    FROM krrg_setting_groups g
WHERE s.group_id = g.id
  AND (s.is_admin IS NULL OR g.code <> 'admin');

UPDATE krrg_settings s
SET is_admin = TRUE
    FROM krrg_setting_groups g
WHERE s.group_id = g.id
  AND g.code = 'admin';

rollback.sql:
UPDATE krrg_settings SET is_admin = NULL;
UPDATE krrg_setting_groups SET is_admin = NULL;
ALTER TABLE krrg_settings ALTER COLUMN is_admin DROP DEFAULT;
ALTER TABLE krrg_setting_groups ALTER COLUMN is_admin DROP DEFAULT;
